import{G as e,W as t,n,rt as r}from"./chunks/framework.BVvt2_kn.js";import"./chunks/assets.BZpss8I_.js";var i=JSON.parse(`{"title":"歡迎來到MCSM Panel教學","description":"","frontmatter":{},"headers":[],"relativePath":"mcsm.md","filePath":"mcsm.md"}`),a={name:`mcsm.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="歡迎來到mcsm-panel教學" tabindex="-1">歡迎來到MCSM Panel教學 <a class="header-anchor" href="#歡迎來到mcsm-panel教學" aria-label="Permalink to “歡迎來到MCSM Panel教學”">​</a></h1><h2 id="進入面板並登入" tabindex="-1">進入面板並登入 <a class="header-anchor" href="#進入面板並登入" aria-label="Permalink to “進入面板並登入”">​</a></h2><p>先輸入管理員給您的帳號以及密碼</p><p>輸入完之後在點擊下方的登入</p><p><img src="/assets/mcsm_login.DDft2Q3u.png" alt="An image" width="1919" height="904"></p><h2 id="登入完成後介紹面板" tabindex="-1">登入完成後介紹面板 <a class="header-anchor" href="#登入完成後介紹面板" aria-label="Permalink to “登入完成後介紹面板”">​</a></h2><p><img src="/assets/mcsm_home.CQ9uDjwe.png" alt="An image" width="1919" height="910"></p><p>登入後，會有實例清單 (您的伺服器)</p><p>左側有 主題(深色.淺色) . 個人資料(不會用到) . 登出(字面意思)</p><p>我們先來看實例清單我們點擊「進入控制台」</p><p><img src="/assets/mcsm_server.BNsCKPrw.png" alt="An image" width="1440" height="223"></p><p>進入控制台後，你會看到 控制台 功能組 等</p><p>點進去檔案管理</p><p><img src="/assets/mcsm_file.h5GMeIMb.png" alt="An image" width="1672" height="909"></p><p>檔案管理的旁邊有新增，我們點新增檔案</p><p>空白檔案 --&gt; 管理員通知您啟動檔案是啥(例如 : app.py 就填寫app.py)</p><p>填寫完畢後點進去，我們寫個print來做測試</p><p><img src="/assets/mcsm_app.SBW1wmL6.png" alt="An image" width="465" height="170"></p><p>寫完之後點下方「儲存」</p><p>儲存完畢後回到終端機，點啟動</p><p><img src="/assets/mcsm_go.DY4JlSA2.png" alt="An image" width="1455" height="260"></p><p><strong>情況2:</strong></p><p>您選擇上傳Bot檔案</p><p>同樣的，若是管理員跟你說你的啟動檔案為app.py</p><p>那你機器人啟動的檔案若是其他名字，請更改為app.py</p><p>您的機器人才能正常運作。</p><h2 id="到這裡就可以啦" tabindex="-1">到這裡就可以啦~ <a class="header-anchor" href="#到這裡就可以啦" aria-label="Permalink to “到這裡就可以啦~”">​</a></h2><p>趕快試試看吧</p><h2 id="下一頁" tabindex="-1">下一頁 : <a class="header-anchor" href="#下一頁" aria-label="Permalink to “下一頁 :”">​</a></h2><p>下一頁為「Pterodactyl面板教學」</p><p>請點擊「Next page」開始教學</p>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};